/**
 * Contract types acceptance (brief criterion 12).
 *
 * Sources: app/web/CLAUDE.md rule 2 ("Types come from contracts/ts/ (generated by
 * scrubgpt-codegen). Never hand-write or edit contract types. Import them through a Vite/TS path
 * alias (e.g. @contracts → ../../contracts/ts)"), root CLAUDE.md (`schema/` and `ts/` are generated;
 * never edit by hand), app/web/README.md (`import type { Case } from "@contracts/contracts"`).
 */
/// <reference types="node" />
import { readFileSync } from "node:fs";
import { resolve } from "node:path";

import { describe, expect, it } from "vitest";

// Read as text from the file system: the generated file is outside the Vite root. vitest runs in
// app/web (the npm scripts), so the repo root is two folders up.
const contractsTs = readFileSync(resolve(process.cwd(), "../../contracts/ts/contracts.ts"), "utf8");

const sources = import.meta.glob<string>(["/src/**/*.{ts,tsx}", "!/src/**/*.test.{ts,tsx}"], {
  query: "?raw",
  import: "default",
  eager: true,
});

/** Every type or interface name the generated contracts file exports. */
const contractNames = [...contractsTs.matchAll(/^export\s+(?:interface|type)\s+([A-Za-z0-9_]+)/gm)].map((m) => m[1]!);

describe("Contract types (CLAUDE.md rule 2)", () => {
  it("the generated contracts are reachable through the @contracts alias", () => {
    expect(contractNames.length).toBeGreaterThan(30);
    for (const name of ["Case", "Bilingual", "TrustLabel", "Moment", "ProcedureReference", "ApiError", "ErrorCode"]) {
      expect(contractNames).toContain(name);
    }
  });

  it("src/ was found by the scan", () => {
    expect(Object.keys(sources).length).toBeGreaterThan(5);
  });

  it("no file in src/ declares a type or interface with a contract type's name", () => {
    const offenders: string[] = [];
    for (const [file, raw] of Object.entries(sources)) {
      // Import and re-export statements (`import { type Case } from …`) are uses, not declarations.
      const text = raw.replace(/(?:import|export)\s[^;]*?from\s+["'][^"']+["'];?/g, "");
      for (const m of text.matchAll(/(?:^|\s)(?:export\s+)?(?:declare\s+)?(?:interface|type|enum|class)\s+([A-Za-z0-9_]+)/g)) {
        if (contractNames.includes(m[1]!)) offenders.push(`${file}: ${m[1]}`);
      }
    }
    expect(offenders).toEqual([]);
  });

  it("no file in src/ copies a contract enum as a string-literal union", () => {
    // e.g. a hand-written `"ai_detected" | "dataset_annotation" | …` instead of `TrustLabel`.
    const unions = [...contractsTs.matchAll(/^export type ([A-Za-z0-9_]+) =\s*((?:\s*\|?\s*"[^"]+")+);/gm)]
      .map((m) => ({ name: m[1]!, literals: [...m[2]!.matchAll(/"([^"]+)"/g)].map((x) => x[1]!) }))
      .filter((u) => u.literals.length >= 3);
    expect(unions.map((u) => u.name)).toEqual(expect.arrayContaining(["TrustLabel", "Role", "MomentKind", "CaseSource"]));
    const offenders: string[] = [];
    for (const [file, text] of Object.entries(sources)) {
      for (const u of unions) {
        const literal = u.literals.map((l) => `"${l}"`).join(String.raw`\s*\|\s*`);
        if (new RegExp(literal).test(text)) offenders.push(`${file}: ${u.name}`);
      }
    }
    expect(offenders).toEqual([]);
  });

  it("contract types are imported from @contracts (never from a relative contracts/ path)", () => {
    const offenders: string[] = [];
    let aliasImports = 0;
    for (const [file, text] of Object.entries(sources)) {
      if (/from\s+["'](?:\.\.\/)+.*contracts\/ts/.test(text)) offenders.push(file);
      if (/from\s+["']@contracts\/contracts["']/.test(text)) aliasImports += 1;
    }
    expect(offenders).toEqual([]);
    expect(aliasImports).toBeGreaterThan(0);
  });
});
